#include <LiquidCrystal.h>

LiquidCrystal lcd (A0, A1, A2, A3, A4, A5);

byte Or = 0, Not =1, Xor =2, Nor =3, Xnor =4, And =5, Nand =6;

void Msg(bool res);

bool TrueTab(byte prtLgc, int s, int a, int b=0, int c=0, int d=0, int e=0);

void setup() {
  lcd.begin(16, 2);
  lcd.print("<<Test Arduino>>");
  lcd.setCursor(0,1);

  Msg(TrueTab(Nand, 3,2,1));
}

void loop() {
}
void Msg (bool res){
  String msg = res ? "  ok CI ": " Def/Desc ";
  
  for(int i=0; i<8; i++){
    lcd.setCursor(0,1);
    lcd.print("                ");
    delay(400);
    lcd.print(msg);
    delay(800);
  }
}
bool TrueTab (byte prtLgc, int s, int a, int b, int c, int d, int e){
 (s < 8)? s-=1 : s-=2; 
 (a < 8)? a-=1 : a-=2;
 (b < 8)? b-=1 : b-=2;
 (c < 8)? c-=1 : c-=2; 
 (d < 8)? d-=1 : d-=2;
 (e < 8)? e-=1 : e-=2;
 
 pinMode (s, INPUT); pinMode (a, OUTPUT);
 if (b >-1) pinMode (b, OUTPUT);
 if (c >-1) pinMode (c, OUTPUT);
 if (d >-1) pinMode (d, OUTPUT);
 if (e >-1) pinMode (e, OUTPUT);

 
bool trueTab[2][2][2][2][2]={0};
bool _not = false;

if(prtLgc == And) trueTab[1][1][1][1][1] = 1;
else if(prtLgc == Not) trueTab[1][1][1][1][0] = 1; 
else if(prtLgc == Or){
  trueTab[e ==-1][d == -1][c ==-1][0][0]= 1;
  _not = true;
}
else if(prtLgc == Nand){
  trueTab[1][1][1][1][1] = 1;
  _not = true;
}
else if(prtLgc == Xor){
  trueTab [1][1][1][0][1] = 1;
  trueTab [1][1][1][1][0] = 1;
}
else if(prtLgc == Xnor){
  trueTab [1][1][1][0][0] = 1;
  trueTab [1][1][1][1][1] = 1;
}
else if(prtLgc == Nor){
  trueTab [e ==-1][d == -1][c ==-1][0][0]= 1;
}
 for(int i=0; i<2; i++) {
  for(int j=0; j<2; j++) {
    for(int k=0; k<2; k++) {
      for(int m=0; m<2; m++) {
        for(int n=0; n<2; n++) {
      }
    }
    digitalWrite(a,n);
    if(b > -1) digitalWrite(b,m); else m = 1;
    if(c > -1) digitalWrite(c,k); else k = 1;
    if(d > -1) digitalWrite(d,j); else j = 1;
    if(e > -1) digitalWrite(e,i); else i = 1;
    
    if(!_not &&digitalRead(s)!= trueTab[i][j][k][m][n]) return 0;
    if(_not &&digitalRead(s) == trueTab[i][j][k][m][n]) return 0; 

     }
    }
   }
  }
 }
