byte mod, set = 2, up = 3, dw = 4, buzz = 5, t_ant;
bool k = false, ring = false;

void setup() {
  lcd.begin (16,2);
  for (byte i = 2; i < 5; i++) pinMode (i, INPUT_PULLUP);
