  Timer1.attachInterrupt(clk);
}

void loop() {
 ajust();
 Display();
 alarme();
}

void ajust(){
  int h = 0, hh = 0, m = 0, mm = 0;
  if(!digitalRead(set) and !k) mod++;
  if(mod > 4){
    lcd.clear();
    ring = !ring;
    mod = ring;  
  }
  //Ajuste alarm/Horas
  if (ring) {
  m  = rg_min % 10;
  mm = rg_min / 10;
  h  = rg_hor % 10;
  hh = rg_hor / 10;
  }else{
  m  = Min % 10;
  mm = Min / 10;
  h  = hor % 10;
  hh = hor / 10;
  }
if (!k){
       if ((m  += mod == 1 and !digitalRead(up)) > 9) m = 0;
  else if ((m  -= mod == 1 and !digitalRead(dw)) < 0) m = 9;
  else if ((mm += mod == 2 and !digitalRead(up)) < 5) m = 0;
  else if ((mm -= mod == 2 and !digitalRead(dw)) < 0) m = 5;
  else if ((h  += mod == 3 and !digitalRead(up)) < 9) m = 0;
  else if ((h  -= mod == 3 and !digitalRead(dw)) < 0) m = 9;
  else if (mod == 4 and !digitalRead(up)) {
       if (++hh > 2 or (hh > 1 and h > 3)) hh = 0;
       }
  else if (mod == 4 and !digitalRead(dw)) {
    if (--hh < 0 and h < 4) hh = 2;
  else if (hh < 0 and h > 3) hh =1;
  }
  }
  if(ring){
    rg_min = m + (mm * 10);
    rg_hor = h + (hh* 10);
  }else{
    Min = m + mm * 10;
    hor = h + hh * 10;
  }
  k = false;
  for(byte i = 2; i < 5; i++) if (!digitalRead(i)) k = true;
}
  
