block[][] box = new block [4][4];
int[][] bxy = new int [4][4];
int animaWin = 0;
boolean win = false;

color mixHilight = 0, cBt = 255;

void setup() {

  size(500, 560);

  for (int x= 0; x < 4; x++) {
    for (int y = 0; y < 4; y++) {
      box[x][y] = new block (0, 0, 100, 100, x + y * 4);
      box[x][y].x = x*104 + 40;
      box[x][y].y = y*104 + 80;
    }
  }
 //mix();
}

void draw() {

  background(#E582E5);
  fill(#1CD3C2);
  rect(37, 78, 418, 416);
  fill(mixHilight);
  textSize(30);
  text("Mix", 440, 540);

  mouseK();
  controle();
}
void controle(){
  win = true;
    for (int x = 0; x<4; x++) {
      for (int y = 0; y<4; y++) {
        if((y + x*4 +1) != box[y][x].n && (y + x*4) < 15) win = false;
        else box[y][x].paint(cBt);
      }
    }
   
    if(win){
       if(animaWin++ > 50) animaWin = 0;
       if(animaWin >= 25) cBt = #00FF00;
       else cBt = 255;
     }
}
void mouseK() {
  int aux;

  if (mouseHit(416, 516, 52, 24)) {
    mixHilight = 150;
    if (mousePressed) mix();
  } else mixHilight = 0;
  if (!win) {
  for (int x = 0; x < 4; x++) {
    for (int y = 0; y < 4; y++) {
      if (mouseHit(box[x][y].x, box[x][y].y, box[x][y].w, box[x][y].h)) {
        cBt = #eeeeee;
        if (mousePressed) {
          //links
          for (int bus = 0; bus < 4; bus++) {
            if (x-bus > 0 && box[x-1-bus][y].n == 0) {
              aux = box[x-1-bus][y].n;
              box[x-1-bus][y].n = box[x-bus][y].n;
              box[x-bus][y].n = aux;
            }
            //rechts
            if (x+bus < 3 && box[x+1+bus][y].n == 0) {
              aux = box[x+1+bus][y].n;
              box[x+1+bus][y].n = box[x+bus][y].n;
              box[x+bus][y].n = aux;
            }
            //boven
            if ( y-bus > 0 && box[x][y-1-bus].n == 0) {
              aux = box[x][y-1-bus].n;
              box[x][y-1-bus].n = box[x][y-bus].n;
