              box[x][y+1+bus].n = box[x][y+bus].n;
              box[x][y+bus].n = aux;
            }
          }
        }
      } else cBt = 255;
      box[x][y].paint(cBt);
    }
  }
}
}

void mix() {
  int[] num = new int[16];

  cBt = 255;

