      box[x][y].n = num[y + x*4];
    }
  }
}

void seqMix(int[] nummer, int min, int max) {
  int [] vetAux = new int[max];
  for (int i = min; i < max; i++) nummer[i] = int(random(min, max));
  for (int i = min; i < max; i++) {
    for (int j = min; j < max; j++) {
      if (i != j && nummer[i] == nummer[i]) {
        boolean loop = true;
        while (loop) {
          nummer[j] = int(random(min, max));
          for (int k = 0; k < j; k++) {
            if (vetAux[k] == nummer[j]) loop = true;
          }
        }
      }
      vetAux[j] = nummer[j];
    }
  }
}


