public void KeyTyped(KeyEvent e){}

public void keyPressed(KeyEvent e){
  if(e.getKeyCode()==37){
    esquerda=true;
  }
  if(e.getKeyCode()==38){
    cima=true;
  }
  if(e.getKeyCode()==39){
    direita=true;
  }
  if(e.getKeyCode()==40){
    baixo=true;
  }
}

public void keyReleased(KeyEvent e){
  if(e.getKeyCode()==37){
    esquerda=false;
  }
  if(e.getKeyCode()==38){
    cima=false;
  }
  if(e.getKeyCode()==39){
    direita=false;
  }
  if(e.getKeyCode()==40){
    baixo=false;
  }
}
}

