    BITMAP  *buffer   = create_bitmap( 800, 600);
    BITMAP  *esquerda = load_bitmap("esquerda.bmp",NULL);
    BITMAP  *direita  = load_bitmap("direita.bmp",NULL);
    BITMAP  *baixo    = load_bitmap("baixo.bmp",NULL);
    BITMAP  *cima     = load_bitmap("cima.bmp",NULL);
    BITMAP  *fundo    = load_bitmap("fundo.bmp",NULL);
    BITMAP  *face     = esquerda;
    //sons

    SAMPLE *wave = load_sample("wave.wav");
    MIDI   *midi = load_midi("midi.mid");

    play_midi(midi, TRUE);

    while(!key[KEY_ESC])
    {
      //Entradas
      if (key[KEY_RIGHT]){x -= 1; face = esquerda;}
      if (key[KEY_LEFT]) {x += 1; face =  direita;}
