      if (key[KEY_DOWN]) {y -= 1; face =     cima; play_sample(wave, 255, 128, 1000, 0);}

      //circlefill(buffer, x, y, 100, makecol(255, 245, 200));
      draw_sprite(buffer, fundo, 0, 0);
      draw_sprite(buffer, face, 100 + x, 100 + y);
      draw_sprite(screen, buffer, 0, 0);
      rest(5);
      clear(buffer);

    }    
    destroy_bitmap(esquerda);
    destroy_bitmap (direita);
    destroy_bitmap  (buffer);
    destroy_bitmap    (cima);
    destroy_bitmap   (fundo);
    destroy_bitmap   (baixo);
    destroy_sample    (wave);
    destroy_midi      (midi);

    return 0;
}

